import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        vm.assume(sender != address(0));
        vm.assume(target != address(0));
        // Configure flash governance to allow the call
        c.configureFlashGovernance(address(this), 1, 0, false);
        c.endConfiguration();
        // Ensure configured is true initially
        assertTrue(c.configured());
        // Call assertGovernanceApproved (will revert due to missing transferFrom, but we catch)
