pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        vm.assume(sender != address(0) && target != address(0));
        vm.assume(sender != address(this) && target != address(this));

        // Set up governance so that sender is the DAO (which passes flashEnabled check)
        // Because c.DAO() is address(this) from setUp, we prank as this
        vm.prank(address(this));

        // We need to make the call revert-safe to observe the rule
        // The rule: after the call, configured() == false if the call reverted, == true otherwise
        // But in reference, configured is always true after a successful call.
        // In mutant, configured remains false.

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted == !c.configured());
    }
}

