pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure sender is a governed address or the DAO to avoid flashEnabled modifier revert
        vm.assume(sender == address(this) || c.governed(sender));

        bool configuredBefore = c.configured();

        // Call assertGovernanceApproved - it may revert depending on conditions
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        if (!success) {
            // If it reverted, configured should remain unchanged
            assertTrue(c.configured() == configuredBefore, "configured changed after revert");
        } else {
            // If it succeeded, configured should still be unchanged (the reference never changes configured)
            assertTrue(c.configured() == configuredBefore, "configured changed after success");
        }
    }
}

