pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newDAO, address caller) public {
        // Ensure that we don't violate the precondition of setDAO
        // The require statement allows: caller == address(0) OR caller == c.DAO() OR !c.configured()
        // We need to find a valid call where configured() changes incorrectly.
        // The bug is in setDAO: it sets configured = true unconditionally.
        // The original only deletes governer, leaving configured unchanged.
        // So we test: after calling setDAO by an unauthorized caller (who is NOT the DAO and DAO is not zero),
        // the configured state should remain false (since the call should revert).
        // But if the caller is the DAO, it is allowed and we expect configured to stay the same.
        // Let's set up the scenario where DAO is non-zero and caller is not the DAO.
        // The only way to set DAO initially is through constructor OR setDAO.
        // In setUp, we created C with address(this) as DAO (via constructor).
        // So DAO is non-zero. 
        // Now we call setDAO from a random caller.
        vm.assume(caller != address(this) && caller != address(0));
        vm.prank(caller);
        // This call should ideally revert in the reference because configured=true? No, configured is false initially.
        // Actually the require is: DAO == address(0) || msg.sender == DAO || !configured.
        // Since DAO is address(this) (constructor), msg.sender != DAO, and configured is false, so !configured is true.
        // So the call succeeds in both reference and buggy.
        // But the bug sets configured = true, while reference does not.
        // So after this call, configured will be true in buggy, false in reference.
        // We can then test: after calling setDAO with an unauthorized but allowed caller (since !configured),
        // configured must remain false.

        bool configuredBefore = c.configured();
        c.setDAO(newDAO);
        bool configuredAfter = c.configured();

        // The rule: configured must never change from false to true due to setDAO (unless called by DAO).
        // But here caller is not DAO, so configured should stay false.
        assertTrue(configuredAfter == configuredBefore, "configured changed incorrectly");
    }
}

